const apiKey = $getEnvironmentVariable('YOUTUBE_DATA_API_KEY');
const sources = $input.all()[0].json || [];
const results = [];

async function resolveChannelId(handleOrId) {
  // If already starts with UC and is 24 chars, treat as channel ID
  if (/^UC[A-Za-z0-9_-]{22}$/.test(handleOrId)) {
    return handleOrId;
  }
  // Handle @channelname or channel name
  const handle = handleOrId.startsWith('@') ? handleOrId.slice(1) : handleOrId;
  const url = `https://www.googleapis.com/youtube/v3/channels?part=id&forHandle=${encodeURIComponent(handle)}&key=${apiKey}`;
  const res = await $httpRequest({ method: 'GET', url, responseFormat: 'json', timeout: 15000 });
  if (!res.items || res.items.length === 0) {
    throw new Error(`Could not resolve channel handle: ${handleOrId}`);
  }
  return res.items[0].id;
}

async function fetchChannelVideos(channelId) {
  const url = `https://www.googleapis.com/youtube/v3/search?part=snippet&channelId=${encodeURIComponent(channelId)}&maxResults=25&order=date&type=video&key=${apiKey}`;
  return await $httpRequest({ method: 'GET', url, responseFormat: 'json', timeout: 20000 });
}

for (const source of sources) {
  try {
    const channelId = await resolveChannelId(source.url);
    const data = await fetchChannelVideos(channelId);
    const videos = (data.items || []).map((item) => {
      const videoId = item.id?.videoId;
      const snippet = item.snippet || {};
      if (!videoId) return null;
      return {
        source_id: source.id,
        source_url: `https://www.youtube.com/watch?v=${videoId}`,
        canonical_url: `https://www.youtube.com/watch?v=${videoId}`,
        content_hash: videoId,
        source_type: 'video',
        original_language: source.language || 'en',
        category_id: source.category_id,
        title: snippet.title || '',
        published_date: snippet.publishedAt,
        featured_image_url: snippet.thumbnails?.high?.url || snippet.thumbnails?.default?.url,
        status: 'pending',
        fetch_error: null
      };
    }).filter(Boolean);
    results.push(...videos.map(v => ({ json: v })));
  } catch (err) {
    results.push({
      json: {
        source_id: source.id,
        step: 'fetch',
        status: 'error',
        message: err.message || 'YouTube fetch failed'
      }
    });
  }
}
return results;

// Separate errors from valid videos
const all = $input.all();
const errors = all.filter(i => i.json.step === 'fetch' && i.json.status === 'error');
const videos = all.filter(i => !i.json.step && !i.json.fetch_error);
return [...videos, ...errors];

const duplicate = $input.all();
const item = $input.first().json;

if (item.step && item.status === 'error') {
  return [{ json: item }];
}

if (duplicate.length === 0 || !duplicate[0].json.id) {
  return [{ json: item }];
}

return [{ json: { source_id: item.source_id, step: 'dedupe', status: 'skipped', message: 'Duplicate: ' + item.source_url } }];

const item = $input.first().json;
if (item.id) {
  return [{ json: { article_id: item.id, source_id: item.source_id, step: 'fetch', status: 'success', message: 'YouTube video ingested' } }];
}
if (item.step) {
  return [{ json: item }];
}
return [];
